"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[94],{6303:e=>{e.exports=JSON.parse('{"functions":[{"name":"synsaveinstance","desc":"Save the current place, one [Instance], or a group of [Instance]s. Example:\\n```lua\\nlocal Params = {\\n\\tRepoURL = \\"https://raw.githubusercontent.com/luau/UniversalSynSaveInstance/main/\\",\\n\\tSSI = \\"saveinstance\\",\\n}\\n\\nlocal synsaveinstance = loadstring(game:HttpGet(Params.RepoURL .. Params.SSI .. \\".luau\\", true), Params.SSI)()\\n\\nlocal CustomOptions = { SafeMode = true, DecompileTimeout = 15, SaveBytecode = true }\\n\\nsynsaveinstance(CustomOptions)\\n```\\n\\nYou can pass any number of arguments, in any order:\\n```lua\\nsynsaveinstance({ mode = \\"scripts\\" }, \\"myScripts.rbxlx\\")\\nsynsaveinstance(workspace.Model) -- Object; saved as a model\\nsynsaveinstance({ workspace.Model, workspace.OtherModel }) -- ExtraInstances\\n```","params":[{"name":"...","desc":"[UniversalSynSaveInstance.CustomOptions] tables are combined in order. An [Instance] becomes `Object`. A string becomes `FilePath`. A list of Instances becomes `ExtraInstances` and sets `IsModel = true`. If you pass Instances directly and do not set `mode`, `mode` becomes invalid, so only those Instances are saved.","lua_type":"table | Instance | string"}],"returns":[],"function_type":"static","yields":true,"source":{"line":3701,"path":"saveinstance.luau"}}],"properties":[],"types":[{"name":"CustomOptions","desc":"Options for [UniversalSynSaveInstance.synsaveinstance]. All fields are optional.\\nThe default is shown at the end of each field. Option names are not\\ncase-sensitive: `NilInstances`, `nilinstances`, and `nilInStaNces` are the\\nsame option. Unknown names are ignored.","fields":[{"name":"mode","lua_type":"string","desc":"What to save. `optimized` saves the most important services (Workspace, Players, Lighting, ReplicatedStorage, StarterGui, and others). `full` saves everything under `game`. `scripts` saves only the top-level parts that contain a [LuaSourceContainer] (a script object). It saves the whole part, not just the script. Any other value saves only `ExtraInstances` (and `Object`, if set). If `Object` is set, `optimized` becomes `full`. ___Default:___ `optimized`"},{"name":"Binary","lua_type":"boolean","desc":"Save a binary file (`.rbxl`/`.rbxm`) instead of an XML file (`.rbxlx`/`.rbxmx`). Binary files are smaller and load faster. If the executor cannot write binary data correctly, the script uses XML. Set the old option `XML = true` to force XML. ___Default:___ true"},{"name":"CompressionMode","lua_type":"string | boolean","desc":"How to compress (make smaller) the binary file: `\\"zstd\\"`, `\\"lz4\\"`, or `false` for no compression. `true` means `\\"zstd\\"`. The old option `DisableCompression = true` means `false`. ___Default:___ `\\"zstd\\"`"},{"name":"CompressionLevel","lua_type":"number","desc":"Compression level for zstd, from -7 to 22. A higher level makes a smaller file but takes longer. This is ignored for lz4 and when compression is off. ___Default:___ 9"},{"name":"FilePath","lua_type":"string | false","desc":"File name to save to. You can include a folder. If the name has no extension, the script adds one based on `Binary` and `IsModel`. If you set this, the script overwrites an existing file and ignores `AvoidFileOverwrite`. ___Default:___ false"},{"name":"SafeMode","lua_type":"boolean","desc":"Disconnect the LocalPlayer from the game when saving starts. This turns on `KillAllScripts` and `BoostFPS` unless you set them yourself. **HIGHLY RECOMMENDED.** ___Default:___ false"},{"name":"KillAllScripts","lua_type":"boolean","desc":"Close or disable other running scripts before saving. `SafeMode` turns this on. Some games stop responding to input after this. That is normal. **HIGHLY RECOMMENDED.** ___Default:___ false"},{"name":"BoostFPS","lua_type":"boolean","desc":"Turn off 3D rendering while saving, then turn it back on. `SafeMode` turns this on. ___Default:___ false"},{"name":"Object","lua_type":"Instance | false","desc":"Save this [Instance] instead of the whole place. The script saves a model if you do not set `IsModel = false`. If you pass `game`, it saves the place and uses `full` mode. You must pass an [Instance], not a name. ___Default:___ false"},{"name":"IsModel","lua_type":"boolean","desc":"Save a model (`.rbxm`/`.rbxmx`) instead of a place (`.rbxl`/`.rbxlx`). `Object` turns this on unless you set it yourself. Passing a list of Instances as an argument also turns it on. ___Default:___ false"},{"name":"ShowStatus","lua_type":"boolean","desc":"Show a status label on the screen. It shows the size while saving, then the final size and time. ___Default:___ true"},{"name":"ReadMe","lua_type":"boolean","desc":"Add a README script to the save. It contains save details (place ID, date, time, platform, executor, recovered scripts, warnings) and tips. ___Default:___ true"},{"name":"Decompile","lua_type":"boolean","desc":"Turn the compiled script back into source code (decompile). This replaces the `Source` of each [LuaSourceContainer] with decompiled code. If this is off, `Source` says decompiling is disabled. ___Default:___ true"},{"name":"SaveBytecode","lua_type":"boolean","desc":"If the executor supports `getscriptbytecode`, add the compiled script data (bytecode) to `Source` as a comment. You can decompile it later. This respects `DecompileIgnore`. ___Default:___ false"},{"name":"DecompileTimeout","lua_type":"number","desc":"How many seconds one decompile call can take. If it takes longer, the script stops waiting and writes a timeout message in `Source`. Set to -1 to disable the timeout. ___Default:___ 10"},{"name":"BytecodeTimeout","lua_type":"number","desc":"How many seconds a `getscriptbytecode` call can take. If it takes longer, the script stops waiting and skips the bytecode for that script. Set to -1 to disable the timeout. ___Default:___ 3"},{"name":"DecompileIgnore","lua_type":"{Instance | string} | {[Instance | string]: boolean | {[string]: boolean}}","desc":"Skip decompiling matched [Instance]s and their children. `Source` becomes a short ignored message. You can pass an [Instance], a class name, or `ClassName = {Name1, Name2}`. Set an [Instance] to `false` to skip only that instance, not its children. ___Default:___ {TextChatService}"},{"name":"DecompileJobless","lua_type":"boolean","desc":"Only use scripts that are already in the decompile cache. Missing scripts get a short not-found message. This turns on `scriptcache`. ___Default:___ false"},{"name":"scriptcache","lua_type":"boolean","desc":"If the executor supports `getscriptbytecode`, cache decompiled code. This avoids decompiling the same script twice. The cache stays after the script reloads. ___Default:___ true"},{"name":"RecoverScriptsFromAssets","lua_type":"boolean","desc":"Recover the original `Source` of scripts that were published as assets. Changes made after publishing are not included. ___Default:___ true"},{"name":"IsolatePlayers","lua_type":"boolean","desc":"Put every [Player] under a top-level `\\"Players\\"` Folder instead of inside the [Players] service. This turns on `SaveNotCreatable`. If both are on, this option is used instead of `IsolateLocalPlayer`. ___Default:___ false"},{"name":"IsolateLocalPlayer","lua_type":"boolean","desc":"Save the LocalPlayer as a Folder named `\\"LocalPlayer\\"` instead of a [Player] object. This is ignored if `IsolatePlayers` is on. ___Default:___ false"},{"name":"IsolateLocalPlayerCharacter","lua_type":"boolean","desc":"Save LocalPlayer.Character as a [Model] named `\\"LocalPlayer Character\\"`. This saves the character even when characters are normally skipped. ___Default:___ false"},{"name":"IsolateStarterPlayer","lua_type":"boolean","desc":"Put [StarterPlayer]\'s children under a top-level `\\"StarterPlayer\\"` Folder. The original service stays, but it is empty. ___Default:___ false"},{"name":"SavePlayerCharacters","lua_type":"boolean","desc":"Save player characters instead of skipping them. This also saves objects with `Archivable = false`, so `IgnoreNotArchivable` is forced on. ___Default:___ false"},{"name":"NilInstances","lua_type":"boolean","desc":"Include objects that have no parent (they are not under `game`). This needs the executor function `getnilinstances`. When that function exists, it also turns on `SaveNotCreatable`. ___Default:___ false"},{"name":"ExtraInstances","lua_type":"{Instance}","desc":"A list of [Instance]s to add to the normal save. If `mode` is not a valid value, only these Instances (and `Object`, if set) are saved. Passing a list of Instances as an argument fills this list. ___Default:___ {}"},{"name":"IgnoreList","lua_type":"{Instance | string} | {[Instance | string]: boolean | {[string]: boolean}}","desc":"Objects to skip. Use an [Instance] or a class name as a key to skip that object and its children. `ClassName = false` keeps the object but skips its children. `ClassName = {Name1, Name2}` skips objects with those names. You can also pass a list of Instances or class names. ___Default:___ {CoreGui, CorePackages, Packages = false}"},{"name":"IgnoreSpecialProperties","lua_type":"boolean","desc":"Do not use the executor function `gethiddenproperty`. Other property reads still work. This can help if your executor crashes or the file is corrupted. ___Default:___ false"},{"name":"AlternativeWritefile","lua_type":"boolean","desc":"Write the file in smaller pieces with `appendfile` instead of one `writefile` call. For binary saves, if `appendfile` fails, it uses `writefile`; if both fail, it switches to XML. ___Default:___ true"},{"name":"Anonymous","lua_type":"boolean | {Name: string?, UserId: number?}","desc":"**RISKY:** Replace LocalPlayer.Name and UserId in the output. `true` replaces them with `\\"Roblox\\"` and `1`. You can also pass a table with `Name` and/or `UserId`. Name matching ignores case. This can also change other text or numbers that match. ___Default:___ false"},{"name":"RiskyServicesDisabled","lua_type":"{UGC: boolean?, Encoding: boolean?, Reflection: boolean?}","desc":"Turn off services that some games may detect. `UGC` skips [UGCValidationService] (used for some hidden properties). `Encoding` skips [EncodingService]. `Reflection` skips [ReflectionService] (used for class data). Set a flag to `true` to skip that service. If you do not set `RiskyServicesDisabled` yourself, the UGC fallback turns on automatically when `gethiddenproperty` is missing. ___Default:___ {UGC = true, Encoding = false, Reflection = false}"},{"name":"AvoidFileOverwrite","lua_type":"boolean","desc":"If `FilePath` is not set, add (1), (2), ... to the file name instead of overwriting an existing file. ___Default:___ true"},{"name":"AntiIdle","lua_type":"boolean","desc":"Stop Roblox from kicking you for being idle (not moving) for 20 minutes. ___Default:___ true"},{"name":"CopyToClipboard","lua_type":"boolean","desc":"Copy the result to the clipboard (the copy/paste buffer) instead of writing a file. Your executor must support `setrbxclipboard`. Use this only for small saves. ___Default:___ false"},{"name":"Callback","lua_type":"((data: string, chunks: {string}) -> ()) | false","desc":"Call this function with the result instead of writing a file. It receives the full text and a list of chunks. If `CopyToClipboard` is also on, the clipboard is used instead. ___Default:___ false"},{"name":"IgnoreProperties","lua_type":"{string}","desc":"A list of property names to skip on every object. For example: `{\\"Tags\\", \\"AttributesSerialize\\"}`. ___Default:___ {}"},{"name":"IgnoreNotArchivable","lua_type":"boolean","desc":"Save objects even when their `Archivable` property is `false`. If this is off, the script skips those objects. ___Default:___ true"},{"name":"SaveNotCreatable","lua_type":"boolean","desc":"Save classes that Roblox says are not creatable. The script replaces them with a class it can create, using `NotCreatableFixes` (usually `Folder`). This turns on automatically with `IsolatePlayers`, `IsolateLocalPlayer`, and `NilInstances` (when `getnilinstances` exists). ___Default:___ false"},{"name":"NotCreatableFixes","lua_type":"{string} | {[string]: string | false}","desc":"Replace a class with a class that can be created. The default replacement is `\\"Folder\\"`. A list of class names also becomes `Folder`. Built-in changes: [Player], [PlayerGui], [PlayerScripts], [TouchTransmitter], and others become `Folder`; [CloudLocalizationTable] becomes [LocalizationTable]; `Platform` becomes [Part]; `Status` becomes [Model]. Set a class to `false` to skip its replacement. ___Default:___ built-in replacements"},{"name":"NilInstancesFixes","lua_type":"{[string]: ((instance: Instance, overrides: table) -> Instance?) | false}","desc":"Where to put objects that have no parent. For example, it puts [Animator] under an [AnimationController]. Built-in fixes exist for [Animator], [AdPortal], [Attachment], [BaseWrap], and [PackageLink]. Child classes use the parent fix ([Bone]s use the Attachment fix). Set a class to `false` to turn off its fix. ___Default:___ built-in Animator/AdPortal/Attachment/BaseWrap/PackageLink fixes"},{"name":"IgnoreDefaultProperties","lua_type":"boolean","desc":"Skip properties that already have the default value for their class. This only affects XML output. Binary output does not use this option. ___Default:___ true"},{"name":"IgnorePropertiesOfNotScriptsOnScriptsMode","lua_type":"boolean","desc":"Only in `scripts` mode: save properties for [LuaSourceContainer]s and skip properties for all other objects. This does nothing in other modes. ___Default:___ false"},{"name":"IgnoreDefaultPlayerScripts","lua_type":"boolean","desc":"Skip Roblox\'s default player scripts (`PlayerModule`, `BubbleChat`, `ChatScript`, `PlayerScriptsLoader`, `RbxCharacterSounds`). This can stop some executors from crashing during decompile. ___Default:___ false"},{"name":"SaveCacheInterval","lua_type":"number","desc":"How much XML data the script holds in memory while saving. Lower values update the status more often but are slower. This does not write to disk. When `KillAllScripts` is on, this also sets the script timeout between 20 and 30 seconds. ___Default:___ 0x1600 * 10"},{"name":"SharedBinaryStrings","lua_type":"boolean","desc":"Store the same binary data (meshes, images, ...) only once in the file. This makes saves with repeated data smaller. Files with all unique data can get slightly bigger. This is not an official Roblox format, but Studio can still open the file. ___Default:___ false"},{"name":"TreatUnionsAsParts","lua_type":"boolean","desc":"Change all [PartOperation]s (unions and intersections) into [Part]s. **RISKY:** you lose the merged shape, but executors that cannot read unions will still show visible parts. ___Default:___ false"},{"name":"ShutdownWhenDone","lua_type":"boolean","desc":"Close the game after a successful save. ___Default:___ false"},{"name":"__DEBUG_MODE","lua_type":"boolean | ((...any) -> ())","desc":"Print debug warnings for unusual cases. If you pass a function, the script uses it instead of `warn`. ___Default:___ false"}],"source":{"line":3639,"path":"saveinstance.luau"}},{"name":"OptionsAliases","desc":"Map of old option names to new option names for the [UniversalSynSaveInstance.CustomOptions] table.\\nFormat: `{ OldName = NewName }`\\nThe script reads these before your options, so you cannot change them after the script starts.","fields":[{"name":"Clipboard","lua_type":"string","desc":"`CopyToClipboard`"},{"name":"DecompileScripts","lua_type":"string","desc":"`Decompile`"},{"name":"FileName","lua_type":"string","desc":"`FilePath`"},{"name":"IgnoreArchivable","lua_type":"string","desc":"`IgnoreNotArchivable`"},{"name":"IgnoreDefaultProps","lua_type":"string","desc":"`IgnoreDefaultProperties`"},{"name":"InstancesBlacklist","lua_type":"string","desc":"`IgnoreList`"},{"name":"IsolatePlayerGui","lua_type":"string","desc":"`IsolateLocalPlayer`"},{"name":"SaveCharacters","lua_type":"string","desc":"`SavePlayerCharacters`"},{"name":"SaveLocalPlayer","lua_type":"string","desc":"`IsolateLocalPlayer`"},{"name":"SaveNilInstances","lua_type":"string","desc":"`NilInstances`"},{"name":"SaveNonCreatable","lua_type":"string","desc":"`SaveNotCreatable`"},{"name":"SavePlayerGui","lua_type":"string","desc":"`IsolateLocalPlayer`"},{"name":"SavePlayers","lua_type":"string","desc":"`IsolatePlayers`"},{"name":"ShowProgress","lua_type":"string","desc":"`ShowStatus`"},{"name":"StatusText","lua_type":"string","desc":"`ShowStatus`"},{"name":"timeout","lua_type":"string","desc":"`DecompileTimeout`"}],"source":{"line":3661,"path":"saveinstance.luau"}},{"name":"OptionsAliasesInverse","desc":"Map of old option names that change a true/false value to the opposite.\\nFormat: `{ OldName = NewName }`\\nThe script flips the value before it uses it. `noscripts = true` sets `Decompile = false`.\\n`DisableCompression = true` sets `CompressionMode = false`.\\nThe script reads these before your options, so you cannot change them after the script starts.","fields":[{"name":"DisableCompression","lua_type":"string","desc":"`CompressionMode`"},{"name":"noscripts","lua_type":"string","desc":"`Decompile`"},{"name":"RemovePlayerCharacters","lua_type":"string","desc":"`SavePlayerCharacters`"},{"name":"RemovePlayers","lua_type":"string","desc":"`IsolatePlayers`"},{"name":"XML","lua_type":"string","desc":"`Binary`"}],"source":{"line":3674,"path":"saveinstance.luau"}}],"name":"UniversalSynSaveInstance","desc":"This module saves the current place, one [Instance] (a Roblox object), or a\\ngroup of [Instance]s to a `.rbxl`/`.rbxm` (binary) or `.rbxlx`/`.rbxmx` (XML)\\nfile.\\n\\nAll options are optional. See\\n[UniversalSynSaveInstance.CustomOptions] for all options. Option names are not\\ncase-sensitive. Old names from [UniversalSynSaveInstance.OptionsAliases] and\\n[UniversalSynSaveInstance.OptionsAliasesInverse] also work.\\nThe most common options are at the top of\\n[UniversalSynSaveInstance.CustomOptions]. Related options are grouped\\ntogether, and advanced or rarely used options are at the bottom.","source":{"line":3583,"path":"saveinstance.luau"}}')}}]);